steps.run:
cargo metadata --locked --no-deps --format-version 1 > /tmp/package-metadata.json
node --input-type=module <<'JS'
import fs from 'node:fs';
const d = JSON.parse(fs.readFileSync('/tmp/package-metadata.json'));
const p = d.packages.find(p => p.manifest_path === `${process.env.GITHUB_WORKSPACE}/Cargo.toml`);
if (!p || JSON.stringify(p.publish) !== '["crates-io"]'
  || p.repository !== `https://github.com/${process.env.GITHUB_REPOSITORY}`) {
  throw new Error('Public package metadata is not the reviewed crate');
}
fs.appendFileSync(process.env.GITHUB_ENV, `PACKAGE_ARCHIVE=target/package/${p.name}-${p.version}.crate\n`);
fs.appendFileSync(process.env.GITHUB_OUTPUT, `version=${p.version}\n`);
JS

node --input-type=module <<'JS'
import assert from 'node:assert/strict'
import {readFileSync} from 'node:fs'
import {createHash} from 'node:crypto'
import {execFileSync} from 'node:child_process'
import {createRequire} from 'node:module'
import {resolve} from 'node:path'
const name='@zixcel/interaction', repository='zixcel/zixcel-interaction', env=process.env
assert.equal(env.GITHUB_REPOSITORY,repository);assert.equal(env.GITHUB_REF,'refs/heads/main')
assert.equal(env.GITHUB_EVENT_NAME,'workflow_dispatch');assert.equal(env.GITHUB_SHA,env.EXPECTED_SOURCE_SHA)
assert(/^[a-f0-9]{40}$/.test(env.EXPECTED_SOURCE_SHA));assert(/^[a-f0-9]{64}$/.test(env.EXPECTED_ARCHIVE_SHA256))
assert(!env.NPM_TOKEN&&!env.NODE_AUTH_TOKEN,'token fallback forbidden')
assert(env.ACTIONS_ID_TOKEN_REQUEST_URL&&env.ACTIONS_ID_TOKEN_REQUEST_TOKEN,'GitHub OIDC unavailable')
assert.equal(execFileSync('npm',['--version'],{encoding:'utf8'}).trim(),'11.12.1')
const require=createRequire(resolve(execFileSync('npm',['root','-g'],{encoding:'utf8'}).trim(),'npm/package.json'))
const semver=require('semver'), data=readFileSync('incoming/package.tgz')
assert.equal(createHash('sha256').update(data).digest('hex'),env.EXPECTED_ARCHIVE_SHA256)
const integrity='sha512-'+createHash('sha512').update(data).digest('base64')
const manifest=JSON.parse(execFileSync('tar',['-xOf','incoming/package.tgz','package/package.json'],{encoding:'utf8'}))
assert.equal(manifest.name,name);assert.equal(semver.valid(manifest.version),manifest.version)
assert(!Object.hasOwn(manifest,'private')||manifest.private===false,'private or invalid private flag')
assert(!Object.hasOwn(manifest,'tag'),'manifest tag override forbidden')
assert(!manifest.publishConfig || Object.keys(manifest.publishConfig).every(k=>['access','registry'].includes(k)))
assert(!manifest.publishConfig?.registry || /^https:\/\/registry\.npmjs\.org\/?$/.test(manifest.publishConfig.registry))
assert(!manifest.publishConfig?.access || manifest.publishConfig.access==='public')
assert.equal(manifest.repository?.url?.replace(/^git\+/,'').replace(/\.git$/,''),'https://github.com/'+repository)
async function metadata(){
 const r=await fetch('https://registry.npmjs.org/'+encodeURIComponent(name),{redirect:'error',signal:AbortSignal.timeout(15000)})
 assert.equal(r.status,200,'Existing public package required; initial publish bootstrap is separate')
 const value=await r.json();assert.equal(value.name,name);assert(value.versions&&value['dist-tags']);return value
}
const before=await metadata(), version=manifest.version
for(const [v,item]of Object.entries(before.versions)){
 assert.equal(semver.valid(v),v,'Unverifiable existing version')
 assert(/^sha512-[A-Za-z0-9+/]{86}==$/.test(item.dist?.integrity),'Existing version SHA512 required')
}
if(before.versions[version]){
 assert.equal(before.versions[version].dist?.integrity,integrity,'Existing version has different bytes')
 console.log('Identical public version already exists; no publish attempted')
}else{
 assert.equal(before['dist-tags'].latest??'<none>',env.EXPECTED_LATEST,'Latest changed or not reviewed')
 assert(!Object.keys(before.versions).some(v=>semver.gte(v,version)),'Higher/equal version exists')
 let failure=false
 try{execFileSync('npm',['publish','incoming/package.tgz','--ignore-scripts','--access=null','--registry=https://registry.npmjs.org/','--fetch-retries=0'],{stdio:'pipe',timeout:120000})}catch{failure=true}
 const after=await metadata()
 for(const [v,item]of Object.entries(before.versions))assert.equal(after.versions[v]?.dist?.integrity,item.dist?.integrity,'Existing integrity changed')
 assert.deepEqual(Object.keys(after.versions).sort(),[...Object.keys(before.versions),version].sort(),'Unexpected version inventory')
 assert.equal(after.versions[version]?.dist?.integrity,integrity,'Published integrity mismatch')
 assert.deepEqual(after['dist-tags'],{...before['dist-tags'],latest:version},'Unexpected dist-tag change')
 if(failure)throw Error('CLI failed; resulting registry state checked; no retry')
 console.log('PASS: OIDC publish and public registry integrity/version/tag verification')
}
JS
